import{navigateTo}from'../shared/navigation-helper.js';export function renderHistory(){const widgetWrapper=document.createElement('div');widgetWrapper.className='history-widget';const title=document.createElement('h3');title.textContent='History';widgetWrapper.appendChild(title);const searchContainer=document.createElement('div');searchContainer.className='history-search-container';const searchInput=document.createElement('input');searchInput.type='text';searchInput.className='history-search-input';searchInput.placeholder='Search history...';searchInput.setAttribute('aria-label','Search history');const clearBtn=document.createElement('button');clearBtn.type='button';clearBtn.className='history-search-clear';clearBtn.innerHTML='&times;';clearBtn.title='Clear search';clearBtn.setAttribute('aria-label','Clear search');clearBtn.style.display='none';searchContainer.appendChild(searchInput);searchContainer.appendChild(clearBtn);widgetWrapper.appendChild(searchContainer);const historyList=document.createElement('ul');historyList.className='history-list';widgetWrapper.appendChild(historyList);function createHistoryItem(item){const li=document.createElement('li');li.className='history-item';const a=document.createElement('a');a.className='shortcut';a.href=item.url;a.title=item.title||item.url;const span=document.createElement('span');span.textContent=item.title||item.url;a.appendChild(span);a.addEventListener('click',(e)=>{e.preventDefault();navigateTo(item.url);});li.appendChild(a);return li;}
let defaultRecentItems=[];function filterValidItems(results){const seenUrls=new Set();const validItems=[];for(const item of(results||[])){if(!item.url||seenUrls.has(item.url))continue;if(item.url.startsWith('chrome-extension://')||item.url.startsWith('chrome://newtab'))continue;seenUrls.add(item.url);validItems.push(item);}
return validItems;}
function renderList(items,isSearch=false){historyList.innerHTML='';if(!items||items.length===0){const empty=document.createElement('li');empty.className='history-empty';empty.style.opacity='0.6';empty.style.padding='8px 4px';empty.style.fontSize='0.9em';empty.textContent=isSearch?'No matching history found':'No recent history';historyList.appendChild(empty);return;}
items.forEach(item=>{historyList.appendChild(createHistoryItem(item));});}
function searchHistory(query){if(!query){renderList(defaultRecentItems,false);return;}
if(typeof chrome!=='undefined'&&chrome.history&&chrome.history.search){chrome.history.search({text:query,maxResults:100,startTime:0},(results)=>{if(typeof chrome!=='undefined'&&chrome.runtime&&chrome.runtime.lastError){console.warn("History search error:",chrome.runtime.lastError);return;}
const validItems=filterValidItems(results);renderList(validItems,true);});}else{const queryLower=query.toLowerCase();const filtered=defaultRecentItems.filter(item=>(item.title&&item.title.toLowerCase().includes(queryLower))||(item.url&&item.url.toLowerCase().includes(queryLower)));renderList(filtered,true);}}
let debounceTimer=null;searchInput.addEventListener('input',()=>{const query=searchInput.value.trim();clearBtn.style.display=searchInput.value.length>0?'flex':'none';clearTimeout(debounceTimer);if(!query){renderList(defaultRecentItems,false);return;}
debounceTimer=setTimeout(()=>{searchHistory(query);},150);});searchInput.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&searchInput.value){e.stopPropagation();searchInput.value='';clearBtn.style.display='none';renderList(defaultRecentItems,false);}});clearBtn.addEventListener('click',()=>{searchInput.value='';clearBtn.style.display='none';renderList(defaultRecentItems,false);searchInput.focus();});if(typeof chrome!=='undefined'&&chrome.history&&chrome.history.search){chrome.history.search({text:'',maxResults:1000,startTime:0},(results)=>{if(typeof chrome!=='undefined'&&chrome.runtime&&chrome.runtime.lastError){console.warn("History error:",chrome.runtime.lastError);return;}
defaultRecentItems=filterValidItems(results);if(!searchInput.value.trim()){renderList(defaultRecentItems,false);}});}else{const empty=document.createElement('li');empty.className='history-empty';empty.style.opacity='0.7';empty.style.padding='10px 4px';empty.style.fontSize='0.85em';empty.style.lineHeight='1.4';empty.innerHTML='History unavailable.<br><span style="text-decoration:underline dotted; cursor:pointer;" title="Click to open extensions page">Reload extension in chrome://extensions</span>';empty.querySelector('span')?.addEventListener('click',()=>{if(typeof chrome!=='undefined'&&chrome.tabs&&chrome.tabs.create){chrome.tabs.create({url:'chrome://extensions'});}else{window.open('chrome://extensions','_blank');}});historyList.appendChild(empty);}
return widgetWrapper;}